INSERT INTO `documents` VALUES (1,'DLv5Jd0MXpogM1pWaA5W7q9miJbngVETYA4ch0gn7ug=','2025-12-12 16:52:41','2025-12-12 16:52:41',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','5.3- Pasaporte actual','pdf',1327865,'Evita introducciones, comentarios, consejos u opiniones, proporciona solo hechos y da una respuesta seca.',1,1,1),(2,'AS3AmpsLCWqCAp0LzI5rBq2YCYLUDYVHfG1xQz1U16k=','2025-12-12 16:52:41','2025-12-12 16:52:41',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','ComprobanteDomicilio','pdf',374212,' Factura Total Play Cliente: Diego Leonardo Reyes Chavez No. Cuenta: 01 40 17 74 04 Teléfono: (55) 97 02 07 57 - Saldo anterior: $0.99 - Cargos del mes (09/feb - 08/mar/2025): - Renta Plan Sónico: $1,138.99 - Suscripciones, TV y Películas: $0.00 - Membresías: $0.00 - Descuentos y Promociones: -$180.00 - Total cargos: $959.00 - Monto a pagar: - Precio lista: $959.00 (vence 13/feb/2025) - Pronto pago: $909.00 (vence 09/feb/2025) - Referencia única de pago: 0900 0001 4017 7404 6 - Métodos de pago: - SPEI (Clabe única: 1271 8090 1401 7740 44) - Tarjetas de crédito/débito (con descuento de pronto pago). - Depósitos en establecimientos (con comisión según sucursal). - Página web y app Totalplay.',1,1,1),(3,'F9L/B1AgVPsgwFF2uzq/WMDFORpcO9t5zz+P8Seqba8=','2025-12-12 16:52:41','2025-12-12 16:52:41',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','CSF','pdf',153751,' Constancia de Situación Fiscal Lugar y Fecha de Emisión: Miguel Hidalgo, Ciudad de México, 24 de noviembre de 2024. Identificación Fiscal: - Cédula de Identificación Fiscal (CIF): RECD920520NA3 - Registro Federal de Contribuyentes (RFC): RECD920520NA3 - CURP: RECD920520HDFYHG06 - Nombre completo: DIEGO LEONARDO REYES CHAVEZ - Fecha de inicio de operaciones: 08 de marzo de 2012 - Estatus en el padrón: ACTIVO Domicilio Registrado: - Colonia: GRANADA - Calle: LAGUNA DE LA MANCHA - Número Exterior: 64 - Entre calles: RIO SAN JOAQUIN y LAGO VICTORIA - Ciudad/Municipio/Estado: Miguel Hidalgo, Ciudad de México, código postal 11520. Actividades Económicas: 1. Comercio al por menor de teléfonos, otros aparatos de comunicación, refacciones y accesorios (35%). 2. Asalariado (30%). 3. Reparación y mantenimiento de otro equipo electrónico y de equipo de precisión (20%). 4. Comercio al por menor de artículos de papelería (15%). Régimen Fiscal: - Régimen de Sueldos y Salarios e Ingresos Asimilados a Salarios (inicio: 01/01/2017). - Régimen de las Personas Físicas con Actividades Empresariales y Profesionales (inicio: 01/01/2022). Obligaciones Fiscales: - Declaración anual de ISR (vencimiento: 30 de abril del ejercicio siguiente). - Pago provisional mensual de ISR (vencimiento: 17 del mes posterior al periodo). - Pago definitivo mensual de IVA (vencimiento: 17 del mes posterior al periodo). - Declaración de proveedores de IVA (vencimiento: último día del mes posterior al periodo). Sello Digital y Cadena Original: - Cadena: 2024/11/24|RECD920520NA3|CONSTANCIA DE SITUACIÓN FISCAL|200001088888800000031 - Sello: MYnSUmDAzR+oOM7vlRNRufPyfJwcHaJkHhqNwrPlRFzR+fKiSS22L4DRXHsg8xEdH64GmVsN6MPf4ib4M/abj7ifVIou4RNcA55dihiLjgZgsosM+Ywzq5l86D/1ejrWRoAUcczQzUz4qcpknxdOAY94CmAGHf99OkH/h80TZBc=.',1,1,1),(4,'vsBvlacuOs5YkU3dx17Yp+2AQWZEQ/63zds6UrJJYas=','2025-12-12 16:52:41','2025-12-12 16:52:41',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','CURP','pdf',78283,NULL,1,1,1),(5,'GGstZx0Kf8/qtVGxTcjTEXqf+uoePm370nNCogg2VIg=','2025-12-12 16:52:41','2025-12-12 16:52:41',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','INE','pdf',1406285,NULL,1,1,1),(6,'u1dImPaqo3+qhM4kICFk6tMXPSnms33GOFQFwL7e9AM=','2025-12-12 17:19:18','2025-12-12 17:19:18',NULL,NULL,2,NULL,3,'uploaded/documents/2/3/','Confirmación _ Viva','pdf',1021130,NULL,1,1,1),(7,'OXUcBI8Keum4KcUd1Mqbg6rTNLe6fINCoqhS3aTcKTg=','2025-12-12 17:19:18','2025-12-12 17:19:18',NULL,NULL,2,NULL,3,'uploaded/documents/2/3/','CV_2025_JJNM','pdf',82975,NULL,1,1,1),(8,'U6r7VsslAuhUO4G5TFaifr3nn51caDdIUD0LU3UElfA=','2025-12-12 17:19:18','2025-12-12 17:19:18',NULL,NULL,2,NULL,3,'uploaded/documents/2/3/','CV_2025_JJNM_ENG','pdf',82721,NULL,1,1,1),(9,'DDUgZ6JF/tfIg1E2CAThpe69QzHt8yHUL/COutRKcAA=','2025-12-12 17:19:18','2025-12-12 17:19:18',NULL,NULL,2,NULL,3,'uploaded/documents/2/3/','CV_MariaBarrera','pdf',80806,NULL,1,1,1),(10,'OL+iwK5iTq2U1rUre1DJ5BkS++t2xozI1C89HSiayQw=','2025-12-18 12:31:09','2025-12-18 12:31:09',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','mifiel_Tabla+de+precios+2023','pdf',3521706,NULL,1,1,1),(11,'U6r7VsslAuhUO4G5TFaifr3nn51caDdIUD0LU3UElfA=','2025-12-18 12:31:49','2025-12-18 12:31:49',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','CV_2025_JJNM_ENG','pdf',82721,NULL,1,1,1),(12,'Ig1AQDxTpYQ6P1pBYEW7DObCeovfIFCRDl1yJh9nEXQ=','2025-12-23 17:19:04','2025-12-23 17:19:04',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','Company TepZ-AGO25 IMPRESION FINAL FIRMA DIGITAL-1','pdf',1821947,' Grupo Tecnológico Quiénes somos: Holding tecnológico en México y LATAM, enfocado en crear, transformar y escalar empresas con propósito, estrategia y sagacidad. Misión: Ser el holding tecnológico más influyente de México y América Latina. Visión: Impulsar la transformación tecnológica del futuro. Valores: Actitud SagaZ (Tecnología con Propósito, Excelencia Estratégica, Proactividad Persistente). Servicios 1. Firma Electrónica: Ofrece firma digital segura (NOM-151), sellos de tiempo y validación biométrica. Disponible en marca blanca y con API. Servicio en `www.cincel.digital`. 2. Fábrica de Software (SaaS Creations): Consultoría, integración de API de firma electrónica, creación de SaaS, OCR y transformación digital. Servicio en `www.saascreations.mx`. 3. OCR con IA: Extracción de datos de PDFs (facturas, documentos gubernamentales, CVs) mediante API. Servicio en `www.saascreations.mx`. 4. Background Check: Verificación de identidad (personas/empresas), crédito, antecedentes (judiciales, penales, listas negras). Servicio en `www.saascreations.mx`. Precios Firma Electrónica: Plan Free: 5 documentos, 1 usuario, 1 equipo, sin API, sin personalización, incluye efirma SAT. Gratis. Plan Business: 100-1500 documentos, 10 usuarios, ilimitados equipos, API, no personalización de correo. $15/certificado, $2/sello, $30/verificación. Plan Pro: 10,000 documentos, 50 usuarios, ilimitados equipos, API, personalización de correo. $12/certificado, $1.20/sello, $30/verificación. Servicios Premium (OCR y Background Check): No detallados en los precios, pero se mencionan como servicios premium. Casos de Uso: Ventas, Legal, RH, Compras, Finanzas, Alta Clientes/Proveedores, Legal (contratos). Casos de Éxito y Soporte: Ofrecen soporte y tienen oficinas en Ciudad de México. Otras Empresas del Grupo: `www.zeroclm.com`, `www.decollectiv.com`.',1,1,1),(13,'NnRBdikYiNDQGg/l7rjGNKfT6a7UemQVrFEKS2+wEEY=','2025-12-23 18:24:14','2025-12-23 18:24:14',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','Ejercicio13_RRR','pdf',131784,'BNO. PASADO Tamaño: A Material: Fundición gris Peso: 3382.11 Unidades: MMGS Escala: 1:2 Hoja: 1 de 1 Producto SOLIDWORKS Educational. Solo para uso en la enseñanza.',1,1,1),(14,'W4kS3KNtNj1xOnpi4ebJ3xpN15zOwtVOOJcHmlWA8G4=','2025-12-24 22:13:57','2025-12-24 22:13:57',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','contrato_final','pdf',28268,'Empresa de Limpieza S.A. contrata a Juan Pérez para limpieza en Calle Principal 123, México D.F. Trabajador: Juan Pérez Lugar: Calle Principal 123, México D.F., C.P. 00000 Salario: 1500.00 pesos mensuales, pagados el 15 de cada mes por transferencia a la cuenta 123456789. Duración: 12 meses, del 01 de octubre de 2023 al 30 de septiembre de 2024. Horario: 8 horas diarias (08:00 a 17:00), descanso viernes. Leyes: Se rige por las leyes mexicanas. Seguridad: Empresa proporcionará ambiente seguro y equipo de protección. Trabajador usará ropa adecuada. Confidencialidad: Trabajador mantendrá en secreto información sobre los hogares y la empresa. Incumplimiento: Empresa podrá suspender el contrato y aplicar sanciones legales. Seguro: Empresa proporcionará seguro de salud básico. Trabajador cubrirá seguro social y requisitos legales. Anexo: Especificaciones de limpieza en anexo.',1,1,1),(15,'u1dImPaqo3+qhM4kICFk6tMXPSnms33GOFQFwL7e9AM=','2025-12-25 16:57:56','2025-12-25 16:57:56',NULL,NULL,2,NULL,2,'uploaded/documents/2/2/','Confirmación _ Viva','pdf',1021130,' Resumen de la reservación: - Número de reserva: QHY3VA - Itinerario: Ciudad de México → Mérida, el 1 de octubre de 2025 (1:00 PM salida, 2:45 PM llegada). - Vuelo: VB 7351, clase E, Terminal NLU a MID. - Pasajeros: Juan Nuñez y Aida Valencia Galicia. - Pago: Realizado con tarjeta, incluye 2 combos Light y 2 maletas de 10 kg. - TUA (Tarifa de Uso de Aeropuerto): Pagada. - Instrucciones: Web check-in, presentar identificación oficial, llegar 2 horas antes del vuelo nacional. - Contacto: Problemas al viaje: contacto@vivaaerobus.com o 88 5536283648.',1,1,1),(16,'2JeEA34CnaGNei+KraRf/EDmMhN+ILGUHZxPrXHYomM=','2025-12-26 19:26:00','2025-12-26 19:26:00',NULL,NULL,3,NULL,4,'uploaded/documents/3/4/','discurso','pdf',50467,' Texto 1: Experiencia en zona de desastre: trabajo desafiante pero gratificante. Se consoló a afectados, se dio esperanza a comunidades. Se demostró humanidad y compasión incluso en momentos difíciles. Se agradeció a compañeros de brigada por su dedicación, compasión y compromiso. Se destacó la resiliencia y fortaleza de las personas afectadas y la unión de las comunidades. Se expresó orgullo por pertenecer al Instituto y por contribuir. Se agradecieron los que apoyaron el trabajo. Texto 2: Discurso sobre atención médica en inundaciones Sierra Hidalgo. Experiencia difícil pero gratificante, destacando la calidad humana de los damnificados y la responsabilidad del personal médico. El trabajo fue arduo pero conmovedor al ver la transformación de la tristeza en sonrisa con el consuelo. El médico cuida la salud física y el alma, dando esperanza. Se destacó la resiliencia y fortaleza de las comunidades afectadas. Se agradeció a los compañeros de brigada y a todas las personas (incl. médicos, enfermeras, transportistas, pilotos, etc.) que colaboraron. Se enfatizó la confianza depositada por los damnificados y la responsabilidad de no defraudarla. Se terminó con un mensaje de que el trabajo llega lejos si se hace con amor.',1,1,1),(17,'Wt7CyK3UCnIczrKlG+nhUqY+GK55VgdTMB6S4Mte5Kc=','2025-12-26 19:26:13','2025-12-26 19:26:13',NULL,NULL,3,NULL,4,'uploaded/documents/3/4/','Mesa','pdf',693669,' Hoja 1: Vista Explosión, Material: ASSEMBLY, Peso: 31005.86, Escala: 1:17, Diseñado por: Ricardo Reyes Razo. Hoja 2: Vista Isométrica, Material: ASSEMBLY, Peso: 31005.86, Escala: 1:17, Diseñado por: Ricardo Reyes Razo. Hoja 3: Vista Explosión, Material: ASSEMBLY, Peso: 31005.86, Escala: 1:20, Diseñado por: Ricardo Reyes Razo. Elementos: Pata (COMPRADO, PA Tipo 6, 41.44, Cantidad: 4) Nivelador (COMPRADO, AISI 1020, 96.13, Cantidad: 4) Perfil vertical (MANUFACTURADO, Aleación 1060, 1120.58, Cantidad: 4) Travesaño1 (MANUFACTURADO, Aleación 1060, 2652.05, Cantidad: 2) Travesaño2 (MANUFACTURADO, Aleación 1060, 1157.94, Cantidad: 2) Adaptador (COMPRADO, Aleación 1060, 108.01, Cantidad: 4) Tabla (MANUFACTURADO, Pino, 17837.48, Cantidad: 1) TornilloRexroth (COMPRADO, 8, Cantidad: 4) TapaMadera (COMPRADO, PVC Rígido, 1.43, Cantidad: 4) TapaPlastico (COMPRADO, PE Alta densidad, 1.04, Cantidad: 8)',1,1,1),(18,'C5VIxGXptZ2MKJB8keSIfM+9agiS9DFhAFq80vVR0Pg=','2025-12-30 17:37:24','2025-12-30 17:37:24',NULL,NULL,1,NULL,1,'uploaded/documents/1/1/','TuBoletoADO','pdf',148158,' Juan de Jesús Núñez Mendoza: Origen: MEXICO TAXQUENA Destino: PUEBLA CAPU Fecha: Viernes 26 Dic 25 Hora Salida: 22:30 h. Noche Tipo Pasaje: ENTERO Precio: $290.00 MXN Pago: TARJETA DE CREDITO Corrida: 153846 Folio: 100155938593 Operación: 200138219880 Aida Guadalupe Valencia Galic: Origen: MEXICO TAXQUENA Destino: PUEBLA CAPU Fecha: Viernes 26 Dic 25 Hora Salida: 22:30 h. Noche Tipo Pasaje: ENTERO Precio: $290.00 MXN Pago: TARJETA DE CREDITO Corrida: 153846 Folio: 100155938594 Operación: 200138219880',1,1,1);
