INSERT INTO `emails` VALUES (1,1,'¡Bienvenido a Signforce! Correo de verificación SIG250109PBA','2025-12-12 14:52:19','thelegendofmax19@gmail.com','Email bienvenida',1,NULL,3),(2,2,'¡Bienvenido a Signforce! Correo de verificación JSTFRTS61526JS','2025-12-12 15:15:23','thelegendofmax19@gmail.com','Email bienvenida',1,NULL,3),(3,2,'¡Tienes una invitación! do.ce.001@proton.me quiere que te unas a SIGNFORCE.','2025-12-12 17:09:29','thelegendofmax19@gmail.com','From: thelegendofmax19@gmail.com\r\nTo: do.ce.001@proton.me\r\nSubject: ¡Tienes una invitación! do.ce.001@proton.me quiere que te unas a SIGNFORCE.\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\nCorreo enviado de Diego Leonardo Reyes Chavez\n\n<!DOCTYPE html>\r\n<html lang=\"es\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Invitación a Equipo – JUSTFRUITS S.A. de C.V.</title>\r\n    <style>\r\n        body {\r\n            background:#001b25;\r\n            min-height:100vh;\r\n            font-family:Inter,Helvetica,sans-serif;\r\n            margin:0;\r\n            display:flex;\r\n            align-items:center;\r\n            justify-content:center;\r\n            color:#eaeaea;\r\n        }\r\n        .container{\r\n            background:#01182075;\r\n            border-radius:16px;\r\n            padding:20px;\r\n            max-width:800px;\r\n            width:100%;\r\n            box-shadow:\r\n                0 8px 32px rgba(0,0,0,.6),\r\n                0 0 20px rgba(4, 0, 253, 0.2);\r\n            border:1px solid rgba(255,255,255,.08);\r\n            text-align:center;\r\n        }\r\n        h1,h2,h3,h4{\r\n            color:#fff;\r\n            margin-bottom:15px;\r\n            line-height:1.8;\r\n        }\r\n        h1{background:#35004366;}\r\n        a{\r\n            color:rgb(255,0,255);\r\n        }\r\n        a:hover{\r\n            color:rgb(0,255,200);\r\n        }\r\n        p{\r\n            margin-bottom:20px;\r\n            font-size:1rem;\r\n            line-height:1.5;\r\n            color:#dcdcdc;\r\n        }\r\n        .cta-button{\r\n            display:inline-block;\r\n            background:#410041;\r\n            color:#fff !important;\r\n            text-decoration:none;\r\n            padding:14px 30px;\r\n            border-radius:10px;\r\n            font-weight:600;\r\n            margin:20px 0;\r\n            transition:.3s ease;\r\n            box-shadow:0 4px 12px rgba(0,0,0,.35);\r\n        }\r\n        .cta-button:hover{\r\n            transform:translateY(-3px);\r\n            background:#660066;\r\n            box-shadow:0 8px 25px rgba(0,0,0,.4);\r\n        }\r\n        .divider{\r\n            height:1px;\r\n            background:linear-gradient(90deg,transparent,#afafaf,transparent);\r\n            margin:30px 0;\r\n        }\r\n        .footer{\r\n            margin-top:30px;\r\n            font-size:.85rem;\r\n            color:#999;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class=\"container\">\r\n    <div class=\"header\">\r\n        <h1>¡Te han invitado a unirte a un equipo!</h1>\r\n    </div>\r\n\r\n    <h4>Hola <strong>do.ce.001@proton.me</strong>,</h4>\r\n\r\n    <p>Has sido invitado por <strong>Diego Leonardo Reyes Chavez</strong> (<a href=\"mailto:do.c.001@hotmail.com\">do.c.001@hotmail.com</a>) para formar parte del equipo en <strong>JUSTFRUITS</strong> (<em>JUSTFRUITS S.A. de C.V.</em>).</p>\r\n\r\n    <div class=\"divider\"></div>\r\n\r\n    <p>Para formar parte del equipo , simplemente haz clic en el botón de abajo.</p>\r\n\r\n    <div style=\"text-align:center;\">\r\n        <a href=\"http://192.168.1.69:8000/viewinviteuser?id=2be2a619-4fee-4362-80f6-29271ceda0cb\" class=\"cta-button\">¡Unirme!</a>\r\n    </div>\r\n\r\n    <p>Esta invitación expirará el <strong>2025-12-17 17:09:28</strong>.</p>\r\n    <p>Si no la aceptas antes de esa fecha, tendrás que solicitar una nueva.</p>\r\n\r\n    <